import csv

def hex_to_words(h):
    r, g, b = int(h[1:3], 16), int(h[3:5], 16), int(h[5:7], 16)
    if abs(r - g) < 40 and abs(g - b) < 40:
        return "neutral grey"
    if g > r and b > r:
        return "teal"
    if r > g and r > b:
        return "warm coral"
    return "beige"

rows = list(csv.DictReader(open("palette/brand_colors.csv")))
primary = next(r for r in rows if r["role"] == "primary")
accent = next(r for r in rows if r["role"] == "accent")

for scene in ["office desk flatlay", "storefront at dusk", "product on pedestal"]:
    print(f"{scene}, dominant {hex_to_words(primary['hex'])} tones, "
          f"{hex_to_words(accent['hex'])} highlights, soft light, editorial photo")

import { buildExportPath } from '../exportPath';

describe('buildExportPath', () => {
  it('puts reports under the tenant folder', () => {
    const p = buildExportPath('/data/exports', 'acme', 'q3 report.csv');
    expect(p).toBe('/data/exports/acme/q3-report.csv');
  });
});

import path from 'path';

export function buildExportPath(root: string, tenant: string, file: string) {
  const safe = file.replace(/\s+/g, '-');
  return path.join(root, tenant, safe);
}
